pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(v[i] == 0 || (v[i] * 1000000000000000000) / v[i] == 1000000000000000000);
        }

        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        try c.transfer(_tos, v) returns (bool r) {
            assertTrue(r);
        } catch {
            // If it reverts, it's not a difference case, so pass
            assertTrue(true);
        }
    }
}

